{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 68세 어머니의 공원 입장료 면제 여부와 공원 내 운동시설 이용료가 전부 무료인지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "68세는 65세 이상이므로 서울특별시 도시공원 조례 제20조제1항제2호에 따라 공원 입장료를 면제받을 수 있습니다. 그러나 공원 내 운동시설 이용료는 제20조제3항제1호에 따라 100분의 50 범위에서 규칙이 정하는 바에 따라 감면될 수 있을 뿐, 전부 무료가 아닙니다. 따라서 입장료 면제와 운동시설 이용료 전액 무료는 별개이며, 운동시설 이용료는 감면 대상이지 전액 무료가 아닙니다.",
          "b_ids": "도시공원:제20조제1항제2호, 도시공원:제20조제3항제1호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
